There seems to be an issue with the backtesting. Let me try a more focused approach, testing individual signal types and then combining the best performing ones.
```python
# Let's test individual signal types to see which ones work well
signal_types = ['hold_', 'tsmom_', 'ma_']

# Test hold signals first
hold_signals = [s for s in signals if s.startswith('hold_')][:10]
hold_weights = {signal: 1.0 for signal in hold_signals}
try:
    sharpe_train, sharpe_val = bt.backtest(hold_weights)
    print("Hold signals - Train: {:.3f}, Val: {:.3f}".format(sharpe_train, sharpe_val))
except:
    print("Hold signals failed")

# Test some tsmom signals
tsmom_signals = [s for s in signals if s.startswith('tsmom_') and s.endswith('_21')][:10]
tsmom_weights = {signal: 1.0 for signal in tsmom_signals}
try:
    sharpe_train, sharpe_val = bt.backtest(tsmom_weights)
    print("TSMOM signals - Train: {:.3f}, Val: {:.3f}".format(sharpe_train, sharpe_val))
except:
    print("TSMOM signals failed")

# Test some MA signals
ma_signals = [s for s in signals if s.startswith('ma_')][:10]
ma_weights = {signal: 1.0 for signal in ma_signals}
try:
    sharpe_train, sharpe_val = bt.backtest(ma_weights)
    print("MA signals - Train: {:.3f}, Val: {:.3f}".format(sharpe_train, sharpe_val))
except:
